<?php elseif($step==='requirements'):?><h2>بررسی نیازمندی‌ها / Requirements</h2><?php foreach($checks as[$label,$ok]):?><div class="req"><span><?=inst_e($label)?></span><b class="<?=$ok?'pass':'fail'?>"><?=$ok?'PASS ✓':'FAIL ✕'?></b></div><?php endforeach?><p>همه موارد باید PASS باشند. / All checks must pass before database setup.</p><?php if($requirementsOk):?><a class="btn primary" href="install.php?step=company">ادامه / Continue</a><?php endif?>
